INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT126-S4-Q8$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Larew's Position$batch07$, $batch07$The lowest quintile's average income rose by a much higher percentage than the highest quintile's, so their prosperity rose relative to the highest.$batch07$), (1, $batch07$Mendota's Position$batch07$, $batch07$"I disagree." The percentage may have been bigger, but the dollar increase was surely bigger for the highest quintile.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$Read Mendota's concession carefully: "may have increased by a greater percentage". Mendota isn't disputing the numbers. Mendota disputes what they show. Larew measures relative prosperity by percentage change; Mendota says the absolute dollar change matters. Picture it: 10% of $10,000 is $1,000, and 5% of $200,000 is $10,000. The gap in dollars grew even though the poorer group's percentage was higher.$batch07$), (3, $batch07$Goal$batch07$, $batch07$Whether comparing percentage changes is the right way to measure relative prosperity.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT126-S4-Q8$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
